// Precomputed Data URIs for optimal CSS background-image performance
export const CARD_BACKGROUND_DATA_URIS = Object.fromEntries(
  Object.entries(CARD_BACKGROUND_SVGS).map(([k, svg]) => [
    k,
    'data:image/svg+xml,' + encodeURIComponent(svg)
  ])
);

export function getCardBackgroundImage(name, isTab = false) {
  if (!name) return '';
  const clean = name.toLowerCase().replace(/\s+/g, '-').replace(/[^a-z0-9\-&]/g, '');
  const cleanWithAnd = clean.replace(/&/g, 'and');
  const cleanWithAmp = clean.replace(/and/g, '&');

  const candidates = isTab
    ? [
        'tab-' + clean,
        'tab-' + cleanWithAnd,
        'tab-' + cleanWithAmp,
        clean,
        cleanWithAnd,
        cleanWithAmp
      ]
    : [
        clean,
        cleanWithAnd,
        cleanWithAmp
      ];

  for (const key of candidates) {
    if (CARD_BACKGROUND_DATA_URIS[key]) {
      return CARD_BACKGROUND_DATA_URIS[key];
    }
  }

  // Fallback to default continuous waves
  return CARD_BACKGROUND_DATA_URIS['on-going-opportunities'] || '';
}

export default getCardBackgroundImage;
